'use strict';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>n==null?'Sin precio':new Intl.NumberFormat('es-CO',{style:'currency',currency:'COP',maximumFractionDigits:0}).format(n),num=n=>new Intl.NumberFormat('es-CO').format(n),safeUrl=u=>{try{const x=new URL(u);return x.protocol==='https:'?x.href:'#'}catch{return '#'}};
let state;try{state=JSON.parse(localStorage.getItem('terreno-v1'))||{}}catch{state={}}
state={city:'Jardín',department:'Antioquia',favorites:[],compare:[],custom:[],notes:{},checks:{},...state};
let catalog={listings:[],runs:[]},tab='discover';const docs=['Certificado de tradición y estudio de títulos','Escritura, área y linderos contrastados','Uso del suelo y norma aplicable por escrito','Licencia de subdivisión / parcelación, si aplica','Determinantes ambientales, agua y vertimientos','Amenaza, riesgo y condiciones geotécnicas','Acceso legal, servidumbres y servicios','Predial, valorización y obligaciones pendientes'];
function persist(){try{localStorage.setItem('terreno-v1',JSON.stringify(state))}catch{toast('No se pudo guardar. Exporta un respaldo.')}}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3500)}
const normalize=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim().toLowerCase();
function all(){return [...catalog.listings,...state.custom].filter(l=>normalize(l.city)===normalize(state.city)&&normalize(l.department)===normalize(state.department))}
function showModal(title,html){$('#modalLabel').textContent=title;$('#modalBody').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}
function navigate(t){tab=t;document.querySelectorAll('.panel').forEach(p=>p.hidden=p.id!==t);document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===t));render();document.body.dataset.view=t;window.scrollTo({top:0,behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}
function card(l){const unit=l.price&&l.area&&!l.price_from?money(Math.round(l.price/l.area)):null;const last=l.history?.at(-1),prev=l.history?.at(-2);let delta=prev&&last&&prev.price&&last.price!==prev.price?`${last.price<prev.price?'↓':'↑'} ${money(Math.abs(last.price-prev.price))} frente a la observación previa`:'Sin variación documentada';return `<article class="card"><div class="cardvisual"><span class="pill">${l.kind==='project'?'Proyecto · precio desde':l.includes_building?'Lote con mejoras':'Anuncio observado'}</span><button data-save="${esc(l.id)}" aria-label="${state.favorites.includes(l.id)?'Quitar de':'Añadir a'} guardados">${state.favorites.includes(l.id)?'♥':'♡'}</button><span class="terrain-number">${esc(l.sector?.slice(0,2).toUpperCase()||'TR')}</span><span class="visualcaption">PAISAJE CONCEPTUAL · NO ES FOTO DEL LOTE</span></div><div class="cardbody"><div class="sector">${esc(l.sector||'Sector por confirmar')} · ${esc(l.city)}</div><h3>${esc(l.title)}</h3><div class="price">${l.price_from?'<small>Desde </small>':''}${money(l.price)}</div><div class="facts"><span>▱ ${l.area?num(l.area)+' m²'+(l.area_from?' desde':''):'Área por confirmar'}</span><span>${unit?unit+' / m²':'$/m² no comparable'}</span></div><div class="progress-inline"><span class="progress-track"><i style="width:${(state.checks[l.id]||[]).length/docs.length*100}%"></i></span><span>${(state.checks[l.id]||[]).length}/${docs.length} documentos revisados por ti</span></div><p class="small">${esc(delta)}${l.includes_building?' · Precio incluye mejoras':''}</p><p class="small">${esc(l.source)} · ${esc(l.observed_at?.slice(0,10)||'Sin fecha')}<br>${l.status==='unavailable'?'Fuente no disponible; venta sin confirmar':l.last_check_status==='error'?'Último intento falló; se conserva la observación previa':'Disponibilidad por confirmar con el anunciante'}</p><div class="cardactions"><button data-detail="${esc(l.id)}">Ver y evaluar ↗</button><button data-compare="${esc(l.id)}">${state.compare.includes(l.id)?'✓ Comparando':'＋ Comparar'}</button></div></div></article>`}
function render(){const items=all();$('#municipality span').textContent=`${state.city}, ${state.department}`;$('#heroCity').textContent=state.city;$('#count').textContent=items.length;$('#savedCount').textContent=items.filter(l=>state.favorites.includes(l.id)).length;$('#compareCount').textContent=state.compare.length;const last=catalog.runs?.filter(r=>normalize(r.city)===normalize(state.city)&&normalize(r.department)===normalize(state.department)).at(-1);$('#lastCheck').textContent=last?.finished_at?new Date(last.finished_at).toLocaleDateString('es-CO',{day:'numeric',month:'short'}):'2 nov 2026';$('#trackingStatus').textContent=last?.method==='source_diversification'?`${last.ok} fichas añadidas · nuevas fuentes`:last?.method==='documentary_review'?`${last.ok} registros consultados · revisión documental`:last?`${last.ok} fuentes actualizadas · ${last.errors} incidencias`:'Captura inicial · programación pendiente en GitHub';$('#catalogNotice').textContent=(catalog.media_update?'Fotos y enlaces consultados: '+catalog.media_update.with_photos+' fichas con fotos. ':catalog.last_update?'Actualización documental: '+catalog.last_update.added+' incorporados y '+catalog.last_update.retained+' conservados. ':'')+'Precios publicados, sin disponibilidad confirmada. Las fotos proceden del anuncio y no acreditan el estado actual del predio.';let list=items.filter(l=>(!$('#advertiser')?.value||l.advertiser_id===$('#advertiser').value)&&(!$('#budget').value||+$('#budget').value===0||l.price&&l.price<=+$('#budget').value)&&(!+$('#area').value||l.area>=+$('#area').value)&&normalize([l.title,l.sector,l.source,l.advertiser].join(' ')).includes(normalize($('#query').value)));const sort=$('#sort').value;list.sort((a,b)=>sort==='price'?(a.price??Infinity)-(b.price??Infinity):sort==='sqm'?((a.price&&!a.price_from&&a.area?a.price/a.area:Infinity)-(b.price&&!b.price_from&&b.area?b.price/b.area:Infinity)):String(b.observed_at).localeCompare(String(a.observed_at)));$('#cards').innerHTML=list.map(card).join('')||`<div class="empty"><h3>${items.length?'Sin resultados con estos filtros.':'Este municipio aún no tiene anuncios cargados.'}</h3><p>Busca en los portales o añade un anuncio. Cambiar de municipio no ejecuta un rastreo remoto.</p><button data-open-sources class="primary">Buscar anuncios ↗</button></div>`;$('#savedCards').innerHTML=items.filter(l=>state.favorites.includes(l.id)).map(card).join('')||'<div class="empty">Guarda un lote con ♡ para seguirlo aquí.</div>';renderCompare();renderAdvice();if(typeof renderInsights==='function')renderInsights()}
function renderCompare(){const ls=[...catalog.listings,...state.custom].filter(l=>state.compare.includes(l.id));$('#comparison').innerHTML=ls.length?`<table><thead><tr><th>Criterio</th>${ls.map(l=>`<th>${esc(l.title)}<br><button data-compare="${esc(l.id)}">Quitar ×</button></th>`).join('')}</tr></thead><tbody>${[['Municipio',l=>`${l.city}, ${l.department}`],['Precio anunciado',l=>(l.price_from?'Desde ':'')+money(l.price)],['Área anunciada',l=>l.area?num(l.area)+' m²'+(l.area_from?' desde':''):'Pendiente'],['Precio / m²',l=>l.price&&l.area&&!l.price_from?money(l.price/l.area):'No comparable'],['Observado',l=>l.observed_at?.slice(0,10)||'Sin fecha'],['Documentos marcados por ti',l=>(state.checks[l.id]||[]).length+' / '+docs.length],['Historial',l=>(l.history||[]).map(h=>h.at.slice(0,10)+': '+money(h.price)).join(' · ')],['Disponibilidad',()=> 'Por confirmar']].map(([k,fn])=>`<tr><td>${k}</td>${ls.map(l=>`<td>${esc(fn(l))}</td>`).join('')}</tr>`).join('')}</tbody></table>`:'<div class="empty">Tu comparación aparecerá aquí. Selecciona hasta tres lotes.</div>'}
function renderAdvice(){const jardin=normalize(state.city)==='jardin'&&normalize(state.department)==='antioquia';$('#territoryText').textContent=jardin?'El EOT de referencia distingue suelo rural, áreas de protección y desarrollo restringido. Confirma la categoría y la norma del predio con Planeación, junto con determinantes ambientales, pendientes, accesos y servicios.':'Aún no hay una revisión territorial específica para '+state.city+'. Solicita POT/PBOT/EOT vigente, cartografía, autoridad ambiental competente y estatuto tributario. No aplicamos las reglas de Jardín a este municipio.';$('#territoryLinks').innerHTML=jardin?'<a href="https://www.antioquiadatos.gov.co/territorio_antioquia/wp-content/uploads/2023/02/Ordenamiento-Municipios/suroeste/jardin.pdf" target="_blank" rel="noopener">EOT de referencia · Antioquia Datos ↗</a><a href="https://www.corantioquia.gov.co/ordenamiento-ambiental-del-territorio/" target="_blank" rel="noopener">Determinantes · Corantioquia ↗</a>':'';const p=$('#purpose').value;$('#creditAdvice').textContent=p==='farm'?'Explora crédito agropecuario vía intermediarios FINAGRO. Elegibilidad, destino, cupos, garantías y tasas requieren confirmación vigente. La ubicación rural por sí sola no concede un subsidio.':p==='tourism'?'Consulta financiación empresarial para el proyecto y compatibilidad del uso turístico. No se presume que una línea agropecuaria financie el lote ni que el turismo esté autorizado.':'Solicita cotización específica para compra de lote o lote más construcción. No asumas cobertura de un crédito de vivienda ni subsidios agropecuarios para una casa de recreo.';calculate()}
function calculate(){const v=id=>Number($('#'+id).value),p=v('cPrice'),down=v('cDown'),ea=v('cRate'),years=v('cYears'),cost=v('cCosts'),annual=v('cAnnual');if([p,down,ea,years,cost,annual].some(n=>!Number.isFinite(n)||n<0)||years<1||years>30||down>p){if($('#financeChart'))$('#financeChart').remove();$('#calcResult').textContent='Revisa los valores: recursos propios ≤ precio, plazo entre 1 y 30 años y valores no negativos.';return}const principal=p-down,r=Math.pow(1+ea/100,1/12)-1,n=years*12,quota=principal===0?0:r===0?principal/n:principal*r/(1-Math.pow(1+r,-n));$('#calcResult').innerHTML=`<div><small>Cuota mensual estimada</small><b>${money(quota)}</b></div><div><small>Desembolso inicial + cierre</small><b>${money(down+cost)}</b></div><div><small>Cuota + provisión mensual</small><b>${money(quota+annual/12)}</b></div><div><small>Intereses en el plazo</small><b>${money(quota*n-principal)}</b></div>`;if(typeof renderFinance==='function')renderFinance({principal,r,n,quota,down,cost,annual})}
function details(id){const l=[...catalog.listings,...state.custom].find(x=>x.id===id);if(!l)return;showModal('FICHA DE EVALUACIÓN',`<h2>${esc(l.title)}</h2><p class="muted">${esc(l.city)} · ${esc(l.sector||'Sector por confirmar')}</p><div class="detailfacts"><div><small>Precio publicado</small><b>${l.price_from?'Desde ':''}${money(l.price)}</b></div><div><small>Área anunciada</small><b>${l.area?num(l.area)+' m²':'Pendiente'}</b></div></div><p>${esc(l.description||'Consulta al anunciante para completar los datos.')}</p><a class="linkbutton" href="${esc(safeUrl(l.url))}" target="_blank" rel="noopener">Abrir fuente original ↗</a><p class="small">Observado: ${esc(l.observed_at)}. La fuente puede haber cambiado. No hay verificación predial independiente.</p><div class="sourcebox"><strong>Procedencia del dato</strong><p>${l.observation_method==='public_web_retrieval'?'Consulta documental mediante recuperación web. La fuente puede proceder de una versión indexada anterior.':'Datos registrados en el radar.'}${l.source_cache_note?' Referencia de indexación: '+esc(l.source_cache_note)+'.':''} Disponibilidad pendiente de confirmar con el anunciante.</p>${l.alternate_urls?.length?'<p>Publicaciones coincidentes: '+l.alternate_urls.map(u=>'<a href="'+esc(safeUrl(u))+'" target="_blank" rel="noopener">Abrir referencia ↗</a>').join(' · ')+'</p>':''}</div><h3>Tu carpeta de verificación</h3><p class="small">Marca solo los documentos que ya revisaste. Esta lista registra tu avance, no certifica la viabilidad.</p>${docs.map((d,i)=>`<label class="docrow"><input type="checkbox" data-doc="${i}" data-id="${esc(id)}" ${(state.checks[id]||[]).includes(i)?'checked':''}>${d}</label>`).join('')}<h3>Historial documentado</h3><p class="small">${(l.history||[]).map(h=>esc(h.at.slice(0,10))+' · '+money(h.price)).join('<br>')||'Sin observaciones históricas.'}</p><label class="form">Notas privadas en este dispositivo<textarea id="lotNotes" placeholder="Documentos recibidos, preguntas, visita…">${esc(state.notes[id]||'')}</textarea></label><p class="small">No se envían a un servidor. Exporta un respaldo desde Guardados.</p><button class="primary" id="saveNotes">Guardar notas</button> <button id="copyQuestions">Copiar preguntas para el vendedor</button>`);$('#saveNotes').onclick=()=>{state.notes[id]=$('#lotNotes').value;persist();toast('Notas guardadas')};$('#copyQuestions').onclick=()=>copy(`Hola, me interesa ${l.title}. ¿Sigue disponible y cuál es el precio actual? ¿Puede compartir matrícula individual, escritura y área, certificado de uso del suelo, licencias aplicables, acceso y servidumbres, disponibilidad de agua y energía, restricciones ambientales y de riesgo, predial y gastos de administración? Gracias.`)}
async function copy(t){try{await navigator.clipboard.writeText(t);toast('Preguntas copiadas')}catch{showModal('COPIAR TEXTO',`<textarea style="width:100%;height:240px">${esc(t)}</textarea>`)}}
function sources(){const q=encodeURIComponent(`lotes venta ${state.city} ${state.department}`);showModal('AMPLIAR TU BÚSQUEDA',`<h2>Explora las fuentes</h2><p>Estas búsquedas se abren en el portal. El catálogo se actualiza por GitHub Actions; este botón no ejecuta un rastreo.</p>${[['Google','https://www.google.com/search?q='+q],['Finca Raíz','https://www.google.com/search?q='+q+'+site%3Afincaraiz.com.co'],['Ciencuadras','https://www.google.com/search?q='+q+'+site%3Aciencuadras.com'],['Mercado Libre','https://www.google.com/search?q='+q+'+site%3Amercadolibre.com.co'],['Facebook (búsqueda manual)','https://www.facebook.com/marketplace/search/?query='+q]].map(([n,u])=>`<p><a href="${u}" target="_blank" rel="noopener">${n} ↗</a></p>`).join('')}<p class="small">Facebook y anuncios no públicos requieren consulta manual. No se accede a sesiones privadas. Añade enlaces relevantes con ＋.</p>`)}
$('#closeModal').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close()}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.tab)navigate(b.dataset.tab);if(b.dataset.save){const id=b.dataset.save;state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];persist();render()}if(b.dataset.compare){const id=b.dataset.compare;if(state.compare.includes(id))state.compare=state.compare.filter(x=>x!==id);else if(state.compare.length<3)state.compare.push(id);else return toast('Compara hasta tres lotes a la vez');persist();render()}if(b.dataset.detail)details(b.dataset.detail);if(b.hasAttribute('data-open-sources'))sources()});
document.addEventListener('change',e=>{if(e.target.dataset.doc!==undefined){const i=+e.target.dataset.doc,id=e.target.dataset.id,a=state.checks[id]||[];state.checks[id]=e.target.checked?[...new Set([...a,i])]:a.filter(x=>x!==i);persist();renderCompare();if(typeof renderInsights==='function')renderInsights()}});
$('#municipality').onclick=()=>{showModal('TU TERRITORIO',`<h2>¿Dónde quieres buscar?</h2><form id="cityForm" class="form"><label>Municipio<input id="newCity" required maxlength="70" value="${esc(state.city)}"></label><label>Departamento<input id="newDepartment" required maxlength="70" value="${esc(state.department)}"></label><p class="small">Jardín es el piloto. Para descubrir anuncios automáticamente de otro municipio, ejecútalo desde Actions → Monitor → Run workflow indicando municipio y departamento. Aquí puedes explorar y guardar anuncios manualmente de inmediato.</p><button class="primary">Cambiar municipio</button></form>`);$('#cityForm').onsubmit=e=>{e.preventDefault();state.city=$('#newCity').value.trim();state.department=$('#newDepartment').value.trim();persist();$('#modal').close();render()}};
$('#add').onclick=()=>{showModal('AÑADIR AL RADAR',`<h2>Un anuncio que encontraste.</h2><form class="form" id="lotForm"><label>Enlace público HTTPS<input id="newUrl" type="url" required placeholder="https://…"></label><label>Título<input id="newTitle" required maxlength="160"></label><label>Sector o vereda<input id="newSector" maxlength="100"></label><label>Precio publicado (COP, opcional)<input id="newPrice" type="number" min="1"></label><label>Área (m², opcional)<input id="newArea" type="number" min="1"></label><p class="small">Se guardará para ${esc(state.city)}, ${esc(state.department)}. Los datos los aportas tú; no se extraen automáticamente del enlace.</p><button class="primary">Guardar anuncio</button></form>`);$('#lotForm').onsubmit=e=>{e.preventDefault();const url=safeUrl($('#newUrl').value);if(url==='#')return toast('Usa un enlace HTTPS válido');const now=new Date().toISOString(),id='local-'+crypto.randomUUID(),price=+$('#newPrice').value||null;state.custom.push({id,title:$('#newTitle').value,sector:$('#newSector').value,price,area:+$('#newArea').value||null,url,city:state.city,department:state.department,source:'Añadido por ti',observed_at:now,history:[{at:now,price}],status:'observed'});state.favorites.push(id);persist();$('#modal').close();render();toast('Anuncio guardado en tu dispositivo')}};
$('#export').onclick=()=>{const blob=new Blob([JSON.stringify({schema:1,exported_at:new Date().toISOString(),state},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='terreno-respaldo.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
$('#import').onchange=async e=>{try{const f=e.target.files[0];if(!f||f.size>3000000)throw Error();const d=JSON.parse(await f.text());if(d.schema!==1||!d.state||typeof d.state.city!=='string'||typeof d.state.department!=='string'||!Array.isArray(d.state.custom)||!Array.isArray(d.state.favorites)||!Array.isArray(d.state.compare)||!d.state.notes||!d.state.checks)throw Error();for(const l of d.state.custom)if(!l||typeof l.id!=='string'||typeof l.title!=='string'||typeof l.city!=='string'||typeof l.department!=='string'||safeUrl(l.url)==='#'||l.price!=null&&(!Number.isFinite(l.price)||l.price<=0)||l.area!=null&&(!Number.isFinite(l.area)||l.area<=0))throw Error();state={...state,...d.state,compare:d.state.compare.slice(0,3)};persist();render();toast('Respaldo importado')}catch{toast('No se pudo importar el respaldo')}e.target.value=''};
for(const id of ['query','budget','area','sort','advertiser'])$('#'+id).addEventListener('input',render);for(const el of document.querySelectorAll('.calcgrid input'))el.addEventListener('input',calculate);$('#purpose').onchange=renderAdvice;$('#explore').onclick=()=>navigate('discover');$('#adviserHero').onclick=()=>navigate('adviser');$('#sourcesBtn').onclick=sources;$('#install').onclick=()=>showModal('EN TU IPHONE','<h2>Tu radar, a un toque.</h2><p>Abre la dirección HTTPS publicada en Safari. Toca Compartir → Añadir a pantalla de inicio → Abrir como app web.</p><p>En GitHub Pages funcionará como una app independiente. Los guardados pertenecen a este navegador; usa un respaldo para trasladarlos.</p>');
(async()=>{try{const r=await fetch('data/catalog.json',{cache:'no-store'});if(!r.ok)throw Error();catalog=await r.json()}catch{toast('No se pudo actualizar el catálogo. Revisa tu conexión.')}render();if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{})})();
